H,W=len(grid),len(grid[0])
for r in range(H):
    for c in range(1,W-1):
        if grid[r][c]==6 and grid[r][c-1]==5 and grid[r][c+1]==5:
            print('h-gap',(r,c))
for r in range(1,H-1):
    for c in range(W):
        if grid[r][c]==6 and grid[r-1][c]==5 and grid[r+1][c]==5:
            print('v-gap',(r,c))

# flood fill: find background(6) regions not touching border
from collections import deque
seen=[[False]*W for _ in range(H)]
regions=[]
for r in range(H):
    for c in range(W):
        if grid[r][c]==6 and not seen[r][c]:
            q=deque([(r,c)]); seen[r][c]=True; reg=[]
            touches=False
            while q:
                a,b=q.popleft(); reg.append((a,b))
                if a in(0,H-1) or b in(0,W-1): touches=True
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<H and 0<=nb<W and grid[na][nb]==6 and not seen[na][nb]:
                        seen[na][nb]=True; q.append((na,nb))
            if not touches: regions.append(reg)
print([(len(x),x) for x in regions])
